"use client";
import { useRef, type ReactNode } from "react";
import {
  useScrollMotion,
  scrollUnits,
  scrollStage,
  type ScrollMotionProps,
  type ScrollItem,
} from "./scroll-shared";
import { scrollRandom, scrollEase, scrollStagger, scrollLerp } from "./scroll-math";
export interface ScatterClusterItem extends ScrollItem {
  /** Final center in percentage coordinates. */ x?: number;
  y?: number;
  width?: number;
  height?: number;
  rotation?: number;
}
export interface ScatterClusterProps extends ScrollMotionProps {
  items: readonly ScatterClusterItem[];
  children?: ReactNode;
  pileRadius?: number;
  pileScale?: number;
  spread?: number;
  stagger?: number;
}
/** Cards retain their DOM identity while an overlapping pile opens around the central content. */
export function ScatterCluster({
  items,
  children,
  pileRadius = 28,
  pileScale = 0.9,
  spread = 1,
  stagger = 0.25,
  ...props
}: ScatterClusterProps) {
  const root = useRef<HTMLDivElement>(null);
  useScrollMotion(
    root,
    props,
    ({ progress: p, width: w, height: h }) => {
      scrollUnits(root.current!).forEach((el, i) => {
        const item = items[i]!,
          a = (i / items.length) * Math.PI * 2 - Math.PI / 2,
          q = scrollEase(scrollStagger(p, i, items.length, stagger));
        const x = (((item.x ?? 50 + Math.cos(a) * 37) - 50) / 100) * w * spread,
          y = (((item.y ?? 50 + Math.sin(a) * 36) - 50) / 100) * h * spread;
        el.style.width = `${Math.min((w * (item.width ?? 21)) / 100, h * 0.33)}px`;
        el.style.height = `${(h * (item.height ?? 27)) / 100}px`;
        el.style.transform = `translate(-50%,-50%) translate(${scrollLerp((scrollRandom(i) - 0.5) * pileRadius * 2, x, q)}px,${scrollLerp((scrollRandom(i, 2) - 0.5) * pileRadius * 2, y, q)}px) rotate(${scrollLerp((scrollRandom(i, 3) - 0.5) * 26, item.rotation ?? 0, q)}deg) scale(${scrollLerp(pileScale, 1, q)})`;
      });
      const text = root.current!.querySelector<HTMLElement>("[data-scroll-center]")!;
      text.style.opacity = String(scrollEase(p));
      text.style.transform = `scale(${0.92 + 0.08 * p})`;
    },
    `${items.map((x) => [x.id, x.x, x.y, x.width, x.height, x.rotation].join(":")).join(",")}:${pileRadius}:${pileScale}:${spread}:${stagger}`,
  );
  return (
    <div
      ref={root}
      data-scroll-animation="scatter-cluster"
      className={props.className}
      style={{ ...scrollStage, ...props.style }}
    >
      <div
        data-scroll-center=""
        style={{
          position: "absolute",
          inset: "28% 27%",
          display: "grid",
          placeContent: "center",
          textAlign: "center",
        }}
      >
        {children}
      </div>
      {items.map((item) => (
        <div
          key={item.id}
          data-scroll-unit={item.id}
          className={item.className}
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            width: `${item.width ?? 21}%`,
            height: `${item.height ?? 27}%`,
            borderRadius: 14,
            overflow: "hidden",
            ...item.style,
          }}
        >
          {item.content}
        </div>
      ))}
    </div>
  );
}

// @zeus-internal
export const scrollClamp = (n: number) => (Number.isFinite(n) ? Math.max(0, Math.min(1, n)) : 0);
export const scrollLerp = (a: number, b: number, p: number) => a + (b - a) * scrollClamp(p);
export const scrollRange = (value: number, start: number, end: number) =>
  start === end ? Number(value >= end) : scrollClamp((value - start) / (end - start));
export const scrollEase = (p: number) => {
  const q = scrollClamp(p);
  return q * q * (3 - 2 * q);
};
export const scrollStagger = (p: number, index: number, count: number, spread = 0.4) => {
  const s = Math.min(0.95, Math.max(0, spread));
  return scrollClamp((p - (index / Math.max(1, count - 1)) * s) / (1 - s));
};
export const scrollRandom = (index: number, seed = 1) => {
  const x = Math.sin((index + 1) * 127.1 + seed * 311.7) * 43758.5453;
  return x - Math.floor(x);
};
export interface ScrollFrame {
  x: number;
  y: number;
  width: number;
  height: number;
  rotation?: number;
  radius?: number;
}
export function scrollFrame(
  frames: readonly ScrollFrame[],
  progress: number,
): Required<ScrollFrame> {
  const p = scrollClamp(progress) * Math.max(0, frames.length - 1),
    index = Math.floor(p);
  const a = frames[index] ?? { x: 0, y: 0, width: 100, height: 100 },
    b = frames[Math.min(index + 1, frames.length - 1)] ?? a;
  return {
    x: scrollLerp(a.x, b.x, p - index),
    y: scrollLerp(a.y, b.y, p - index),
    width: scrollLerp(a.width, b.width, p - index),
    height: scrollLerp(a.height, b.height, p - index),
    rotation: scrollLerp(a.rotation ?? 0, b.rotation ?? 0, p - index),
    radius: scrollLerp(a.radius ?? 0, b.radius ?? 0, p - index),
  };
}
/** Color stops accept CSS hex (3/6 digits) or rgb/rgba. Unknown formats hold until the next stop. */
export function scrollMixColor(a: string, b: string, p: number) {
  const parse = (s: string): number[] | null => {
    const hex = s.replace(/^#/, "");
    if (/^[0-9a-f]{3}$/i.test(hex)) return [...hex].map((x) => parseInt(x + x, 16));
    if (/^[0-9a-f]{6}$/i.test(hex)) return [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16));
    const parts = s
      .match(/^rgba?\(([^)]+)\)$/)?.[1]
      ?.match(/[\d.]+/g)
      ?.map(Number);
    return parts && parts.length >= 3 ? parts : null;
  };
  const ca = parse(a),
    cb = parse(b);
  if (!ca || !cb) return p < 1 ? a : b;
  const channels = [0, 1, 2].map((i) => Math.round(scrollLerp(ca[i]!, cb[i]!, p))).join(", ");
  return ca.length > 3 || cb.length > 3
    ? `rgba(${channels}, ${scrollLerp(ca[3] ?? 1, cb[3] ?? 1, p)})`
    : `rgb(${channels})`;
}

